import{_ as t,o as r,c as a,a0 as i}from"./chunks/framework.Bkgi-hoF.js";const p=JSON.parse('{"title":"Compliance & Security","description":"","frontmatter":{},"headers":[],"relativePath":"compliance/index.md","filePath":"compliance/index.md"}'),o={name:"compliance/index.md"};function n(s,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="compliance-security" tabindex="-1">Compliance &amp; Security <a class="header-anchor" href="#compliance-security" aria-label="Permalink to &quot;Compliance &amp; Security&quot;">​</a></h1><p>@jewel998/config is designed with security and compliance in mind. While we&#39;re not yet certified (SOC 2, ISO 27001), the architecture follows the guidelines and best practices of these frameworks.</p><h2 id="security-architecture" tabindex="-1">Security Architecture <a class="header-anchor" href="#security-architecture" aria-label="Permalink to &quot;Security Architecture&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Protection</th></tr></thead><tbody><tr><td><strong>Authentication</strong></td><td>Firebase Authentication (Google, email/password)</td></tr><tr><td><strong>Authorization</strong></td><td>Per-project RBAC (Viewer, Editor, Admin)</td></tr><tr><td><strong>API Security</strong></td><td>Client/Server key separation, domain validation</td></tr><tr><td><strong>Data Isolation</strong></td><td>Per-project Firestore collections, no cross-project access</td></tr><tr><td><strong>Transport</strong></td><td>HTTPS-only, TLS 1.3 via Firebase Hosting CDN</td></tr><tr><td><strong>Secrets</strong></td><td>API keys are generated with cryptographic randomness</td></tr><tr><td><strong>Audit</strong></td><td>Every mutation recorded with actor, timestamp, before/after</td></tr></tbody></table><h2 id="key-separation" tabindex="-1">Key Separation <a class="header-anchor" href="#key-separation" aria-label="Permalink to &quot;Key Separation&quot;">​</a></h2><p>API keys are typed at creation:</p><ul><li><strong>Client keys (<code>cid_</code>)</strong> — For frontends. The API evaluates targeting server-side and returns only resolved values. Targeting rules, segment definitions, and rollout percentages are never exposed.</li><li><strong>Server keys (<code>svr_</code>)</strong> — For backends. Returns full flag data for local evaluation. Should be stored in environment variables, never in client-side code.</li></ul><p>The API enforces this based on key prefix — no request parameter can override it.</p><h2 id="data-residency" tabindex="-1">Data Residency <a class="header-anchor" href="#data-residency" aria-label="Permalink to &quot;Data Residency&quot;">​</a></h2><p>Your data lives in your own Firebase project. You choose the Firestore region. No data is sent to third-party servers (except webhook endpoints you configure).</p><h2 id="frameworks-we-align-with" tabindex="-1">Frameworks We Align With <a class="header-anchor" href="#frameworks-we-align-with" aria-label="Permalink to &quot;Frameworks We Align With&quot;">​</a></h2><ul><li><a href="/config/compliance/gdpr.html">GDPR</a> — Data minimization, right to deletion, audit trails</li><li><a href="/config/compliance/soc2.html">SOC 2</a> — Access controls, audit logging, change management</li></ul>',12)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
